#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        int temp;
        cin >> temp;
        a[i] = temp % m;
    }

    unordered_set<int> first_half, second_half;

    function<void(unordered_set<int>&, int, int, int)> generate_all_sums = [&](unordered_set<int>& sums_set, int length, int start_idx, int current=0) {
        if (start_idx == length) {
            sums_set.insert(current);
        } else {
            generate_all_sums(sums_set, length, start_idx + 1, (current + a[start_idx]) % m);
            generate_all_sums(sums_set, length, start_idx + 1, current);
        }
    };

    int split_point = n / 2;
    generate_all_sums(first_half, split_point, 0);
    generate_all_sums(second_half, n, split_point);

    vector<int> second_half_vec(second_half.begin(), second_half.end());
    sort(second_half_vec.begin(), second_half_vec.end());

    int best = 0;
    for (auto val : first_half) {
        int pos = (int)(std::lower_bound(second_half_vec.begin(), second_half_vec.end(), m - val) - second_half_vec.begin());
        if (pos > 0) {
            int candidate = val + second_half_vec[pos - 1];
            if (candidate > best) {
                best = candidate;
            }
        }
    }
    cout << best << "\n";

    return 0;
}
